-- CI stub of the raqib schema (test fixture only; never applied to a real server).
--
-- The real mirror and memory tables live in the Raqib repository
-- (raqib/memory-schema.sql and raqib/server/W9-notion-tables.v2.proposed.sql).
-- This stub carries just enough columns for the 0002 GRANTs to resolve and for
-- later joins to be written against real column names.
-- Idempotent: safe to apply before every test.

CREATE SCHEMA IF NOT EXISTS raqib;

CREATE TABLE IF NOT EXISTS raqib.goals (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code text UNIQUE NOT NULL,
  title text NOT NULL,
  track text NOT NULL,
  target_date date NOT NULL,
  acceptance text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  notion_page_id text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS raqib.kpis (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code text UNIQUE NOT NULL,
  name text NOT NULL,
  unit text NOT NULL,
  direction text NOT NULL,
  target numeric,
  target_low numeric,
  target_high numeric,
  frequency text NOT NULL,
  goal_code text REFERENCES raqib.goals (code)
);

CREATE TABLE IF NOT EXISTS raqib.kpi_readings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kpi_code text NOT NULL REFERENCES raqib.kpis (code),
  reading_date date NOT NULL,
  value numeric NOT NULL,
  source text NOT NULL,
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (kpi_code, reading_date, source)
);

CREATE TABLE IF NOT EXISTS raqib.cycles (
  cycle_no smallint PRIMARY KEY,
  stage_no smallint NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  review_start date NOT NULL,
  review_end date NOT NULL,
  theme text NOT NULL,
  season_note text,
  gate text NOT NULL
);

CREATE TABLE IF NOT EXISTS raqib.notion_milestones (
  page_id text PRIMARY KEY,
  title text NOT NULL,
  outcome_code text,
  card_page_ids jsonb NOT NULL DEFAULT '[]'::jsonb,
  cycle_no smallint,
  due_date date,
  done boolean NOT NULL DEFAULT false,
  criterion text,
  evidence text,
  notion_edited_at timestamptz,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  synced_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS raqib.notion_cards (
  page_id text PRIMARY KEY,
  title text NOT NULL,
  status text,
  outcome_codes jsonb NOT NULL DEFAULT '[]'::jsonb,
  props jsonb NOT NULL DEFAULT '{}'::jsonb,
  notion_edited_at timestamptz,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  synced_at timestamptz NOT NULL DEFAULT now()
);

-- Counts-only view over the journal. The stub has no rows; only the column names
-- and types matter.
CREATE OR REPLACE VIEW raqib.v_journal_daily AS
SELECT
  NULL::date AS entry_date,
  NULL::boolean AS morning_done,
  NULL::boolean AS evening_done,
  NULL::boolean AS evening_one_minute,
  NULL::integer AS gratitude_count,
  NULL::integer AS priorities_total,
  NULL::integer AS priorities_reported,
  NULL::integer AS priorities_done,
  NULL::integer AS wins_count,
  NULL::integer AS learnings_count
WHERE false;

-- Decoy: personal journal text that yawmi_api must never be able to read.
CREATE TABLE IF NOT EXISTS raqib.journal_entries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entry_date date NOT NULL,
  raw_reply text
);
